class Uid
{
    /**
     * Generate a cryptographic standard UID.
     *
     * @param string $prefix Entity prefix (e.g. BIL, CYC, ARB, PRD, ORD, EXP, STL)
     * @param int|null $id Optional sequential DB ID to append in parentheses
     * @param string|null $date Custom date or timestamp
     * @return string
     */
    public static function generate(string $prefix, ?int $id = null, ?string $date = null): string
    {
        $dateStr = $date ? date('Ymd', strtotime($date)) : date('Ymd');
        if ($id !== null) {
            $rnd = strtoupper(bin2hex(random_bytes(2))); // 4 hex chars
            return "{$prefix}-{$dateStr}-{$rnd}({$id})";
        }
        $rnd = strtoupper(bin2hex(random_bytes(3))); // 6 hex chars
        return "{$prefix}-{$dateStr}-{$rnd}";
    }

    /**
     * Generate UID for a recurring circle schedule.
     * Format: CIR-YYYYMMDD-XXXXXX
     */
