    /**
     * Generate UID for a bill (archived or one-off bill).
     * Format: BIL-YYYYMMDD-XXXXXX
     */
    public static function forBill(bool $isArchived = true): string
    {
        $dateStr = date('Ymd');
        $rnd = strtoupper(bin2hex(random_bytes(3)));
        return "BIL-{$dateStr}-{$rnd}";
    }

    /**
     * Generate UID for a bill circle / cycle.
     * Format: CYC-YYYYMM-XXXX(ID)
     */
    public static function forCycle(int $cycleId, ?string $dueDate = null): string
    {
        $datePart = $dueDate ? date('Ym', strtotime($dueDate)) : date('Ym');
        $rnd = strtoupper(bin2hex(random_bytes(2)));
        return "CYC-{$datePart}-{$rnd}({$cycleId})";
